AssistantMessageToolRequest(name='create', tool_call_id='tooluse_fmRCE69rILv7ocWXAN6NYo', arguments={'file_text': '/* ── Reset & Tokens ─────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:        #0d0d0d;
  --surface:   #161616;
  --surface2:  #1f1f1f;
  --border:    #2a2a2a;
  --accent:    #e8c56d;
  --accent2:   #c47f3a;
  --text:      #f0f0f0;
  --text-muted:#9a9a9a;
  --red:       #e05252;
  --radius:    10px;
  --transition:0.22s ease;
  --font:      'Inter', system-ui, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; }
button { font-family: inherit; cursor: pointer; border: none; }
ul { list-style: none; }

/* ── Focus Visible ──────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ── Skip Link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  background: var(--accent);
  color: #000;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 700;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Utility ────────────────────────────────────────────────── */
.container { max-width: 1280px; margin: 0 auto; padding: 0 1.5rem; }
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 1.75rem;
  gap: 1rem;
}
.section-header h2 {
  font-size: clamp(1.25rem, 2.5vw, 1.65rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.view-all {
  font-size: 0.85rem;
  color: var(--accent);
  font-weight: 600;
  white-space: nowrap;
  transition: opacity var(--transition);
}
.view-all:hover { opacity: 0.75; }
.badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 0.2em 0.6em;
  border-radius: 4px;
  background: var(--accent);
  color: #000;
}
.badge--red { background: var(--red); color: #fff; }
.badge--new { background: #3b82f6; color: #fff; }

/* ── NAV ────────────────────────────────────────────────────── */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,13,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: 2rem;
}
.nav-logo {
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.04em;
  color: var(--accent);
}
.nav-links {
  display: flex;
  gap: 0.25rem;
}
.nav-links a {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-muted);
  padding: 0.4rem 0.75rem;
  border-radius: 6px;
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover, .nav-links a[aria-current="page"] {
  color: var(--text);
  background: var(--surface2);
}
.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.nav-icon-btn {
  background: none;
  border: 1px solid transparent;
  color: var(--text-muted);
  width: 40px; height: 40px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.nav-icon-btn:hover {
  color: var(--text);
  border-color: var(--border);
  background: var(--surface2);
}
.cart-btn { position: relative; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: #000;
  font-size: 0.6rem;
  font-weight: 800;
  min-width: 16px; height: 16px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  pointer-events: none;
}
.nav-menu-btn { display: none; }

/* ── HERO ────────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: min(600px, 80vh);
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 70% 50%, rgba(232,197,109,0.1) 0%, transparent 65%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(196,127,58,0.08) 0%, transparent 60%);
}
.hero-grid-pattern {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: 0.35;
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 660px;
  padding: 5rem 0;
}
.hero-eyebrow {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 1rem;
}
.hero h1 {
  font-size: clamp(2.4rem, 6vw, 4rem);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.04em;
  margin-bottom: 1.25rem;
}
.hero h1 em {
  font-style: normal;
  background: linear-gradient(90deg, var(--accent), var(--accent2));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero-desc {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 480px;
  margin-bottom: 2.25rem;
}
.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.95rem;
  font-weight: 700;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  transition: opacity var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:hover { opacity: 0.88; transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn--primary {
  background: var(--accent);
  color: #000;
  box-shadow: 0 4px 20px rgba(232,197,109,0.25);
}
.btn--primary:hover { box-shadow: 0 6px 28px rgba(232,197,109,0.38); }
.btn--ghost {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
}
.btn--ghost:hover { background: var(--surface2); }
.hero-stats {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 2.5rem;
  margin-top: 3.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
}
.stat-value { font-size: 1.8rem; font-weight: 800; letter-spacing: -0.04em; color: var(--accent); }
.stat-label { font-size: 0.78rem; color: var(--text-muted); margin-top: 0.1rem; text-transform: uppercase; letter-spacing: 0.06em; }

/* ── MARQUEE BANNER ─────────────────────────────────────────── */
.marquee-banner {
  background: var(--accent);
  color: #000;
  padding: 0.6rem 0;
  overflow: hidden;
}
.marquee-track {
  display: flex;
  gap: 3rem;
  animation: marquee 28s linear infinite;
  white-space: nowrap;
  width: max-content;
}
.marquee-track span {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.marquee-track span::before { content: '✦'; opacity: 0.5; }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) { .marquee-track { animation: none; } }

/* ── SECTION SPACING ────────────────────────────────────────── */
.section { padding: 4.5rem 0; }
.section + .section { border-top: 1px solid var(--border); }

/* ── PRODUCT GRID ───────────────────────────────────────────── */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  position: relative;
}
.product-card:hover {
  border-color: #3a3a3a;
  transform: translateY(-3px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.45);
}
.product-card:focus-within {
  border-color: var(--accent);
}

.product-img-wrap {
  aspect-ratio: 1 / 1;
  overflow: hidden;
  background: var(--surface2);
  position: relative;
}
.product-img-wrap img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.product-card:hover .product-img-wrap img { transform: scale(1.06); }

.product-badges {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  z-index: 1;
}
.product-wishlist {
  position: absolute;
  top: 0.6rem;
  right: 0.6rem;
  z-index: 2;
  background: rgba(13,13,13,0.75);
  border: 1px solid var(--border);
  color: var(--text-muted);
  width: 34px; height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  transition: color var(--transition), background var(--transition);
  backdrop-filter: blur(6px);
}
.product-wishlist:hover { color: #e05252; background: rgba(224,82,82,0.15); }
.product-wishlist[aria-pressed="true"] { color: #e05252; }

.product-info {
  padding: 1rem 1.1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  flex: 1;
}
.product-category {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  font-weight: 600;
}
.product-name {
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--text);
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}
.stars { color: var(--accent); font-size: 0.8rem; letter-spacing: 1px; }
.rating-count { font-size: 0.75rem; color: var(--text-muted); }
.product-price {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  margin-top: auto;
  padding-top: 0.5rem;
}
.price-current { font-size: 1.1rem; font-weight: 700; color: var(--text); }
.price-original { font-size: 0.85rem; color: var(--text-muted); text-decoration: line-through; }
.price-save { font-size: 0.78rem; color: #4ade80; font-weight: 600; }

.product-add-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  width: calc(100% - 2.2rem);
  margin: 0 1.1rem 1.1rem;
  padding: 0.65rem;
  background: var(--surface2);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 7px;
  font-size: 0.875rem;
  font-weight: 600;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
}
.product-add-btn:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: #000;
}
.product-add-btn.added {
  background: rgba(74,222,128,0.1);
  border-color: #4ade80;
  color: #4ade80;
}

/* ── DEALS GRID ─────────────────────────────────────────────── */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.25rem;
}
.deal-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  gap: 1.25rem;
  align-items: center;
  transition: border-color var(--transition), transform var(--transition);
  position: relative;
  overflow: hidden;
}
.deal-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 80% 50%, rgba(232,197,109,0.06), transparent);
  pointer-events: none;
}
.deal-card:hover { border-color: #3a3a3a; transform: translateY(-2px); }
.deal-img {
  width: 90px; height: 90px;
  flex-shrink: 0;
  border-radius: 8px;
  overflow: hidden;
  background: var(--surface2);
}
.deal-img img { width: 100%; height: 100%; object-fit: cover; }
.deal-info { flex: 1; min-width: 0; }
.deal-name { font-size: 0.9rem; font-weight: 600; margin-bottom: 0.4rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.deal-discount { font-size: 1.4rem; font-weight: 800; color: var(--red); letter-spacing: -0.03em; }
.deal-discount span { font-size: 0.75rem; font-weight: 500; color: var(--text-muted); margin-left: 0.3rem; }
.deal-timer {
  display: flex;
  gap: 0.35rem;
  margin-top: 0.75rem;
  align-items: center;
}
.timer-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 0.25rem 0.5rem;
  min-width: 38px;
}
.timer-value { font-size: 0.95rem; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1; }
.timer-label { font-size: 0.6rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.06em; margin-top: 2px; }
.timer-sep { font-size: 1rem; font-weight: 700; color: var(--text-muted); margin-top: -0.2rem; }

/* ── CATEGORIES ─────────────────────────────────────────────── */
.categories-row {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 0.25rem;
}
.categories-row::-webkit-scrollbar { display: none; }
.category-chip {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.65rem;
  padding: 1.25rem 1.5rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  min-width: 100px;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  text-align: center;
}
.category-chip:hover, .category-chip[aria-selected="true"] {
  border-color: var(--accent);
  background: rgba(232,197,109,0.06);
  transform: translateY(-2px);
}
.category-icon {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: var(--surface2);
  display: grid;
  place-items: center;
  font-size: 1.5rem;
}
.category-chip[aria-selected="true"] .category-icon {
  background: rgba(232,197,109,0.15);
}
.category-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-muted);
}
.category-chip[aria-selected="true"] .category-label { color: var(--accent); }

/* ── EDITORIAL ──────────────────────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.25rem;
}
.editorial-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.editorial-card:hover {
  border-color: #3a3a3a;
  transform: translateY(-2px);
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
}
.editorial-card--featured {
  grid-row: 1 / 3;
}
.editorial-img {
  overflow: hidden;
  background: var(--surface2);
}
.editorial-card--featured .editorial-img { aspect-ratio: 3/4; }
.editorial-card:not(.editorial-card--featured) .editorial-img { aspect-ratio: 16/9; }
.editorial-img img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.editorial-card:hover .editorial-img img { transform: scale(1.04); }
.editorial-body {
  padding: 1.25rem 1.4rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  flex: 1;
}
.editorial-tag {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
}
.editorial-title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.35;
}
.editorial-card--featured .editorial-title {
  font-size: 1.25rem;
}
.editorial-excerpt {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.6;
  flex: 1;
}
.editorial-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 0.5rem;
  font-size: 0.78rem;
  color: var(--text-muted);
}
.editorial-author-img {
  width: 24px; height: 24px;
  border-radius: 50%;
  overflow: hidden;
  background: var(--surface2);
  flex-shrink: 0;
}
.editorial-author-img img { width: 100%; height: 100%; object-fit: cover; }
.editorial-read-more {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--accent);
  margin-top: 0.75rem;
  transition: gap var(--transition);
}
.editorial-read-more:hover { gap: 0.6rem; }

/* ── PROMO BANNER ───────────────────────────────────────────── */
.promo-banner {
  margin: 0;
  background: linear-gradient(135deg, #1a1208 0%, var(--surface2) 50%, #120d1a 100%);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  position: relative;
  overflow: hidden;
}
.promo-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 50% 100% at 50% 50%, rgba(232,197,109,0.12), transparent 70%);
  pointer-events: none;
}
.promo-inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  padding: 3.5rem 1.5rem;
  max-width: 1280px;
  margin: 0 auto;
  text-align: center;
}
.promo-text { flex: 1; min-width: 220px; }
.promo-eyebrow {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--accent);
  margin-bottom: 0.75rem;
}
.promo-text h2 {
  font-size: clamp(1.5rem, 3.5vw, 2.4rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.1;
  margin-bottom: 1rem;
}
.promo-text p { font-size: 1rem; color: var(--text-muted); margin-bottom: 1.5rem; }
.promo-code-wrap {
  display: inline-flex;
  align-items: center;
  gap: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  margin-top: 0.5rem;
}
.promo-code {
  padding: 0.6rem 1.2rem;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--accent);
  font-family: monospace;
}
.promo-copy-btn {
  padding: 0.6rem 0.9rem;
  background: var(--surface2);
  border: none;
  border-left: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.8rem;
  font-weight: 600;
  transition: background var(--transition), color var(--transition);
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.promo-copy-btn:hover { background: var(--accent); color: #000; }

/* ── FOOTER ─────────────────────────────────────────────────── */
.site-footer {
  background: var(--surface);
  border-top: 1px solid var(--border);
  padding: 4rem 0 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-brand p {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-top: 0.75rem;
  max-width: 260px;
  line-height: 1.7;
}
.footer-logo {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.04em;
  color: var(--accent);
}
.footer-social {
  display: flex;
  gap: 0.5rem;
  margin-top: 1.25rem;
}
.social-link {
  width: 36px; height: 36px;
  border-radius: 8px;
  border: 1px solid var(--border);
  display: grid;
  place-items: center;
  color: var(--text-muted);
  font-size: 0.9rem;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.social-link:hover {
  color: var(--text);
  border-color: #444;
  background: var(--surface2);
}
.footer-col h4 {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  margin-bottom: 1.1rem;
}
.footer-col ul { display: flex; flex-direction: column; gap: 0.55rem; }
.footer-col a {
  font-size: 0.9rem;
  color: var(--text-muted);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--text); }
.footer-bottom {
  padding-top: 2rem;
  border-top: 1px solid var(--border);
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  font-size: 0.82rem;
  color: var(--text-muted);
}
.footer-payment {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}
.payment-icon {
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.2rem 0.5rem;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text-muted);
}

/* ── TOAST ──────────────────────────────────────────────────── */
#toast-region {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 9999;
  display: flex;
  flex-direction: column-reverse;
  gap: 0.75rem;
  pointer-events: none;
}
.toast {
  background: var(--surface2);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: 8px;
  padding: 0.85rem 1.15rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text);
  box-shadow: 0 8px 32px rgba(0,0,0,0.5);
  animation: slideIn 0.28s ease;
  pointer-events: auto;
  max-width: 300px;
}
.toast.fade-out { animation: fadeOut 0.35s ease forwards; }
@keyframes slideIn {
  from { opacity: 0; transform: translateX(1rem); }
  to   { opacity: 1; transform: translateX(0); }
}
@keyframes fadeOut {
  to { opacity: 0; transform: translateX(1rem); }
}

/* ── RESPONSIVE ─────────────────────────────────────────────── */
@media (max-width: 900px) {
  .editorial-grid {
    grid-template-columns: 1fr;
  }
  .editorial-card--featured { grid-row: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .nav-links { display: none; }
  .nav-menu-btn { display: grid; }
}
@media (max-width: 600px) {
  .hero-content { padding: 3.5rem 0; }
  .hero-stats { gap: 1.5rem; }
  .footer-grid { grid-template-columns: 1fr; }
  .promo-inner { text-align: left; }
  .deals-grid { grid-template-columns: 1fr; }
}
