+.stat-value { font-size: 1.8rem; font-weight: 800; letter-spacing: -0.04em; color: var(--accent); }
+.stat-label { font-size: 0.78rem; color: var(--text-muted); margin-top: 0.1rem; text-transform: uppercase; letter-spacing: 0.06em; }
+
+/* ── MARQUEE BANNER ─────────────────────────────────────────── */
+.marquee-banner {
+  background: var(--accent);
