*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:        #0d0d0d;
  --surface:   #161616;
  --surface2:  #1f1f1f;
  --border:    #2a2a2a;
  --accent:    #e8c56d;
  --accent2:   #c47f3a;
  --text:      #f0f0f0;
  --text-muted:#9a9a9a;
  --red:       #e05252;
  --radius:    10px;
  --transition:0.22s ease;
  --font:      'Inter', system-ui, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; }
button { font-family: inherit; cursor: pointer; border: none; }
ul { list-style: none; }

/* ── Focus Visible ──────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ── Skip Link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  background: var(--accent);
  color: #000;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 700;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Utility ────────────────────────────────────────────────── */
.container { max-width: 1280px; margin: 0 auto; padding: 0 1.5rem; }
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 1.75rem;
  gap: 1rem;
}
.section-header h2 {
  font-size: clamp(1.25rem, 2.5vw, 1.65rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.view-all {
  font-size: 0.85rem;
  color: var(--accent);
  font-weight: 600;
  white-space: nowrap;
  transition: opacity var(--transition);
}
.view-all:hover { opacity: 0.75; }
.badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 0.2em 0.6em;
  border-radius: 4px;
  background: var(--accent);
  color: #000;
}
.badge--red { background: var(--red); color: #fff; }
.badge--new { background: #3b82f6; color: #fff; }

/* ── NAV ────────────────────────────────────────────────────── */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,13,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: 2rem;
}
.nav-logo {
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.04em;
  color: var(--accent);
}
.nav-links {
  display: flex;
  gap: 0.25rem;
}
.nav-links a {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-muted);
  padding: 0.4rem 0.75rem;
  border-radius: 6px;
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover, .nav-links a[aria-current="page"] {
  color: var(--text);
  background: var(--surface2);
}
.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.nav-icon-btn {
  background: none;
  border: 1px solid transparent;
  color: var(--text-muted);
  width: 40px; height: 40px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.nav-icon-btn:hover {
  color: var(--text);
  border-color: var(--border);
  background: var(--surface2);
}
.cart-btn { position: relative; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: #000;
  font-size: 0.6rem;
  font-weight: 800;
  min-width: 16px; height: 16px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  pointer-events: none;
}
.nav-menu-btn { display: none; }

/* ── HERO ────────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: min(600px, 80vh);
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 70% 50%, rgba(232,197,109,0.1) 0%, transparent 65%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(196,127,58,0.08) 0%, transparent 60%);
}
.hero-grid-pattern {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border) 1px, transparent 1px),
    linear-gradient(90deg, var(--border) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: 0.35;
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 660px;
  padding: 5rem 0;
}
.hero-eyebrow {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 1rem;
}
.hero h1 {
  font-size: clamp(2.4rem, 6vw, 4rem);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.04em;
  margin-bottom: 1.25rem;
}
.hero h1 em {
  font-style: normal;
  background: linear-gradient(90deg, var(--accent), var(--accent2));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero-desc {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 480px;
  margin-bottom: 2.25rem;
}
.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.95rem;
  font-weight: 700;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  transition: opacity var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:hover { opacity: 0.88; transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn--primary {
  background: var(--accent);
