}
.btn--primary:hover { box-shadow: 0 6px 28px rgba(232,197,109,0.38); }
.btn--ghost {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
}
.btn--ghost:hover { background: var(--surface2); }
.hero-stats {
  position: relative;
  z-index: 1;
